# try alternative: read top row RIGHT->LEFT (mirrored), cycle down
def cand_mirror(H_top,W,o):
    seq = [o[0][j] for j in range(W-1,-1,-1)] # reversed
    out = []
    for r in range(len(o)):
        if r < H_top:
            out.append(o[r][:])
        else:
            out.append([seq[(r-H_top)%W]]*W)
    return out
out_m=cand_mirror(2,7,G['Demo pair 1 input'])
print('mirror matches?', out_m==G['Demo pair 1 output'])

